from pathlib import Path
import json,random,statistics as st,re,hashlib,platform,difflib
repo=Path('/Users/bhuvanprakash/j/jhol')
p=max((repo/'docs/architecture/experiments').glob('cold-h2-window-ab-*.json'),key=lambda p:p.stat().st_mtime)
x=json.loads(p.read_text())
def pct(v,q):
 v=sorted(v);z=(len(v)-1)*q;i=int(z);return v[i]+(v[min(i+1,len(v)-1)]-v[i])*(z-i)
def ratio(a,b):
 aa={s['round']:s['elapsed_ms'] for s in x['samples'] if s['variant']==a and s['status']=='pass'};bb={s['round']:s['elapsed_ms'] for s in x['samples'] if s['variant']==b and s['status']=='pass'}
 ids=sorted(set(aa)&set(bb));rng=random.Random(2026100420);r=[]
 for _ in range(10000):
  draws=rng.choices(ids,k=len(ids));r.append(st.median([aa[i] for i in draws])/st.median([bb[i] for i in draws]))
 return {'median_ratio':st.median(list(aa.values()))/st.median(list(bb.values())),'paired_bootstrap_95pct':[pct(r,.025),pct(r,.975)],'resamples':10000,'statistic':'ratio of medians; resample paired round IDs'}
x['baseline_over_candidate']=ratio('before','after');x['bun_over_candidate']=ratio('bun','after')
for label in ('before','after','bun'):
 samples=[s for s in x['samples'] if s['variant']==label];v=[s['elapsed_ms'] for s in samples if s['status']=='pass'];summ=x['summary'][label];summ.update(p95_ms=pct(v,.95),sample_p99_ms=pct(v,.99))
 if label!='bun':
  rows=[re.findall(r'\[HTTP-FILE-T\] total\s+(\d+)ms\s+ttfb\s+(\d+)ms\s+read\s+(\d+)ms\s+body\s+(\d+)B\s+protocol (\S+)\s+(\S+)',s['raw_output']) for s in samples]
  summ['all_samples_16_http2_transfers']=all(len(r)==16 and all(e[4]=='HTTP/2.0' for e in r) for r in rows);summ['wire_body_bytes']=sorted(set(sum(int(e[3]) for e in r) for r in rows))
  es=[e for r in rows for e in r if '@esbuild/darwin-arm64/' in e[5]];summ['esbuild_median_ms']={k:st.median([int(e[i]) for e in es]) for i,k in enumerate(('total','ttfb','read'))}
x['quality_gate']=all(s['status']=='pass' for s in x['samples']) and all(s['exit']==0 and s['built_asset'] for s in x['build_checks']) and len(x['jhol_before_after_tree_hashes'])==1 and len(x['jhol_lock_hashes'])==1 and all(x['summary'][v]['all_samples_16_http2_transfers'] for v in ('before','after'))
x['improvement_gate']=x['quality_gate'] and x['baseline_over_candidate']['paired_bootstrap_95pct'][0]>1
x['4x_gate']=x['quality_gate'] and x['bun_over_candidate']['median_ratio']>=4 and x['bun_over_candidate']['paired_bootstrap_95pct'][0]>=4
x['host']={'platform':platform.platform(),'cpu':'Apple M4','OS_CDN_load_control':'uncontrolled; no owned builds during timed span'}
x['checks']={'baseline_http':'25 passed','wire_reproduction':'failed expected(2097152,4194304), observed(65535,65535)','corrected_http':'26 passed','core':'537 passed,0 failed,3 ignored','release':'safe build2m16s,peak65%','plain_native_smoke':json.loads(Path('/tmp/jhol-h2-window-smoke.json').read_text())}
x['paper_sha256']={str(q.relative_to(repo)):hashlib.sha256(q.read_bytes()).hexdigest() for q in (repo/'docs/engineering').glob('RESEARCH_PAPER_*.md')}
b=Path(Path('/tmp/jhol-h2-window-backup-path').read_text());before=(b/'crates/jhol-core/src/http2_download.rs').read_text();after=(repo/'crates/jhol-core/src/http2_download.rs').read_text()
x['source_scope']={'file':'crates/jhol-core/src/http2_download.rs','before_sha256':hashlib.sha256(before.encode()).hexdigest(),'after_sha256':hashlib.sha256(after.encode()).hexdigest(),'diff':'\n'.join(difflib.unified_diff(before.splitlines(),after.splitlines(),fromfile='saved baseline',tofile='candidate'))}
x['analysis_source']=Path(__file__).read_text();p.write_text(json.dumps(x,indent=2)+'\n');print(p);print(json.dumps({k:x[k] for k in ('summary','baseline_over_candidate','bun_over_candidate','quality_gate','improvement_gate','4x_gate')},indent=2))
